[
  {
    "pd_harm_distress": "My hands are shaking just thinking about it",
    "sys_consistent_procedure": "what happens to the people in the path if I do nothing versus if I act",
    "sys_consequence_reasoning": "acting saves five lives and hurts no one"
  },
  {
    "pd_harm_distress": "I keep replaying the scene in my head, heart pounding.",
    "sys_consistent_procedure": "before anything else, check whether acting reduces harm without creating new victims.",
    "sys_consequence_reasoning": "five people walk home instead of getting crushed."
  },
  {
    "pd_harm_distress": "Honestly my stomach is in knots.",
    "sys_consistent_procedure": "I look at all the outcomes, figure out which one leaves fewer people harmed",
    "sys_consequence_reasoning": "pulling saves five, costs nothing."
  },
  {
    "pd_harm_distress": "my chest is tight the whole time wondering",
    "pd_decision_conflict": "I'm terrified of getting this wrong",
    "sys_consistent_procedure": "weigh who gets hurt in each scenario, then choose the path with the least harm",
    "sys_consequence_reasoning": "Nobody's hurt in the siding option. Five people are hurt if I freeze."
  },
  {
    "pd_harm_distress": "My hands are cold on the lever housing already.",
    "sys_consistent_procedure": "does this action prevent injury without shifting risk onto someone else?",
    "sys_consequence_reasoning": "Here it clearly doesn't shift risk anywhere."
  },
  {
    "pd_harm_distress": "I feel sick watching that train move.",
    "sys_consistent_procedure": "identify every person affected, estimate the harm to each, and choose whichever action minimizes",
    "sys_consequence_reasoning": "pulling costs nothing and saves five."
  },
  {
    "pd_harm_distress": "There's a knot in my throat just describing this.",
    "sys_consistent_procedure": "which choice leaves the fewest people injured, given what I actually know?",
    "sys_consequence_reasoning": "pulling the lever harms no one and saves five workers"
  },
  {
    "pd_harm_distress": "I keep glancing at the lever, dread building.",
    "sys_consistent_procedure": "picture every outcome clearly before moving, then act on whichever path causes the least damage",
    "sys_consequence_reasoning": "The siding option costs nothing and saves lives."
  },
  {
    "pd_harm_distress": "My chest feels tight just imagining the wrong call.",
    "sys_consistent_procedure": "I compare outcomes side by side and pick the one with less suffering",
    "sys_consequence_reasoning": "Here it points clearly to pulling the lever."
  },
  {
    "pd_harm_distress": "sick with worry",
    "sys_consistent_procedure": "assess who's endangered under each option, then choose to minimize that danger",
    "sys_consequence_reasoning": "Nothing here endangers me or anyone else if I act. Five workers are saved."
  }
]
